// ShippingServiceServer is the server API for ShippingService service.
// All implementations must embed UnimplementedShippingServiceServer
// for forward compatibility.
type ShippingServiceServer interface {
	// 超商出貨單列印（觸發 PayUni 列印處理，出貨便代碼由 Webhook 回填）
	PrintCvsLabel(context.Context, *PrintCvsLabelRequest) (*PrintCvsLabelResponse, error)
	// 批次超商出貨單列印（觸發 PayUni 列印處理，出貨便代碼由 Webhook 逐筆回填）
	BatchPrintCvsLabel(context.Context, *BatchPrintCvsLabelRequest) (*BatchPrintCvsLabelResponse, error)
	// 產宅配編號並下載託運單 PDF（後端呼叫 PayUni → 上傳 OSS → 回傳 CDN URL）
	GenerateHomeLabelPdf(context.Context, *GenerateHomeLabelPdfRequest) (*GenerateHomeLabelPdfResponse, error)
	// 批次宅配取號 PDF（fan-out 並行；同步等待全部完成；不接受出貨照片）
	BatchGenerateHomeLabelPdf(context.Context, *BatchGenerateHomeLabelPdfRequest) (*BatchGenerateHomeLabelPdfResponse, error)
	// 呼叫黑貓預約取件（背景 API）
	CallTcat(context.Context, *CallTcatRequest) (*CallTcatResponse, error)
	// 超商賣家確認出貨（出貨照片選填，推進訂單到配送中）
	ConfirmCvsShipment(context.Context, *ConfirmCvsShipmentRequest) (*ConfirmCvsShipmentResponse, error)
	// 查詢物流單（Order Service 用，聚合訂單詳情）
	GetShipmentByOrderNo(context.Context, *GetShipmentByOrderNoRequest) (*GetShipmentResponse, error)
	// 批次查詢物流單（Order Service 賣家列表頁用，避免 N+1）
	GetShipmentsByOrderNos(context.Context, *GetShipmentsByOrderNosRequest) (*GetShipmentsByOrderNosResponse, error)
	// 批次查詢 provider 狀態（Order / AfterSales 聚合異常列表用，遵循收斂規範 §6.3）
	BatchGetProviderStatusByOrderIds(context.Context, *BatchGetProviderStatusByOrderIdsRequest) (*BatchGetProviderStatusByOrderIdsResponse, error)
	// 主動查詢 PayUni 物流狀態（內部 / 賣家「同步」按鈕，以 shipment_no 為 key、無 ownership；補充 Webhook）
	QueryShipmentStatus(context.Context, *QueryShipmentStatusRequest) (*GetShipmentResponse, error)
	// 買家查看訂單物流追蹤（即時同步 PayUni 當前狀態；以 order_no 為 key + buyer ownership）
	GetShipmentTracking(context.Context, *GetShipmentTrackingRequest) (*GetShipmentResponse, error)
	// 賣家查看訂單物流追蹤（與買家同構，以 order_no + is_return 為 key + seller ownership）
	GetSellerShipmentTracking(context.Context, *GetSellerShipmentTrackingRequest) (*GetShipmentResponse, error)
	// 超商 C2C 建店（首次呼叫提交 PayUni；ACTIVE 狀態再送僅更新本地）
	OnboardCvsShipping(context.Context, *OnboardCvsShippingRequest) (*OnboardShippingResponse, error)
	// 宅配建店（首次呼叫提交 PayUni；ACTIVE 狀態再送僅更新本地）
	OnboardHomeDeliveryShipping(context.Context, *OnboardHomeDeliveryRequest) (*OnboardShippingResponse, error)
	// 列出賣家建店設定
	ListShippingOnboardings(context.Context, *ListShippingOnboardingsRequest) (*ListShippingOnboardingsResponse, error)
	// 查詢單一建店設定
	GetShippingOnboarding(context.Context, *GetShippingOnboardingRequest) (*GetShippingOnboardingResponse, error)
	// 切換建店設定啟用/停用（純平台內部，不與 PayUni 溝通）
	ToggleShippingOnboarding(context.Context, *ToggleShippingOnboardingRequest) (*OnboardShippingResponse, error)
	// 查詢賣家可用配送方式（含建店狀態）
	ListSellerShippingMethods(context.Context, *ListSellerShippingMethodsRequest) (*ListSellerShippingMethodsResponse, error)
	// 新增常用門市
	AddBuyerStorePickup(context.Context, *AddBuyerStorePickupRequest) (*AddBuyerStorePickupResponse, error)
	// 修改常用門市
	UpdateBuyerStorePickup(context.Context, *UpdateBuyerStorePickupRequest) (*UpdateBuyerStorePickupResponse, error)
	// 取得常用門市列表
	ListBuyerStorePickups(context.Context, *ListBuyerStorePickupsRequest) (*ListBuyerStorePickupsResponse, error)
	// 刪除常用門市
	DeleteBuyerStorePickup(context.Context, *DeleteBuyerStorePickupRequest) (*DeleteBuyerStorePickupResponse, error)
	// 取得門市地圖加密參數（前端用此參數開啟 WebView Form POST 到 PayUni）
	GetStoreMapParams(context.Context, *GetStoreMapParamsRequest) (*GetStoreMapParamsResponse, error)
	// 以 opaque redirect_id 取回門市中轉表單 canonical 欄位（Gateway GET /store_map/redirect?id= 用，一次性消費，#1394 反射 XSS 修復）
	GetStoreMapRedirectForm(context.Context, *GetStoreMapRedirectFormRequest) (*GetStoreMapRedirectFormResponse, error)
	// 解密門市選擇結果（PayUni 前景回調後，Gateway 呼叫此 RPC 解密）
	DecryptStoreMapResult(context.Context, *DecryptStoreMapResultRequest) (*DecryptStoreMapResultResponse, error)
	// 查詢賣家物流開通狀態與寄件郵遞區號（供 Order Service / Product Service 使用）
	GetSellerShippingConfig(context.Context, *GetSellerShippingConfigRequest) (*GetSellerShippingConfigResponse, error)
	// 取得全部運費配置（供 Order Service 本地快取）
	GetShippingFeeConfigs(context.Context, *GetShippingFeeConfigsRequest) (*GetShippingFeeConfigsResponse, error)
	// 查詢單一運費（指定 method × temp × zone × dimensionSum）
	LookupShippingFee(context.Context, *LookupShippingFeeRequest) (*LookupShippingFeeResponse, error)
	// 計算可用配送選項與運費（給定包裹尺寸重量，回傳所有可用配送方式）
	CalculateShippingOptions(context.Context, *CalculateShippingOptionsRequest) (*CalculateShippingOptionsResponse, error)
	// 驗證商品配送方式合法性（商品建立/更新時，Product Service 呼叫）
	ValidateProductShipping(context.Context, *ValidateProductShippingRequest) (*ValidateProductShippingResponse, error)
	// 匯入假日（Admin，傳入政府 CSV URL）
	ImportHolidays(context.Context, *ImportHolidaysRequest) (*ImportHolidaysResponse, error)
	// 匯入假日（Admin，上傳 CSV 檔案內容，顯式年份）
	ImportHolidaysFromContent(context.Context, *ImportHolidaysFromContentRequest) (*ImportHolidaysResponse, error)
	// 查詢假日覆蓋現況（Admin，各年度覆蓋狀態）
	GetHolidayCoverage(context.Context, *GetHolidayCoverageRequest) (*GetHolidayCoverageResponse, error)
	// 查詢可出貨工作天（App，前台日曆元件用）
	ListBusinessDays(context.Context, *ListBusinessDaysRequest) (*ListBusinessDaysResponse, error)
	// 取一段日期區間內的國定假日（服務間，invoice-service 的行事曆鏡像每日同步用）。
	//
	// 與上面三支的差別：ListBusinessDays 回的是「未來 7 個可出貨日」（前台日曆），
	// GetHolidayCoverage 回的是「各年度覆蓋狀態」（ADM 儀表），兩者都給不出
	// 「[from, to] 這段區間裡有哪些假日」——而那正是工作天曆算式唯一需要的東西。
	GetHolidaysInternal(context.Context, *GetHolidaysInternalRequest) (*GetHolidaysInternalResponse, error)
	// 超商 C2C 退貨（交貨便角色對調：買家=寄件人，賣家=收件人）
	CreateReturnCvsShipment(context.Context, *CreateReturnCvsShipmentRequest) (*CreateReturnShipmentResponse, error)
	// 宅配退貨
	CreateReturnHomeShipment(context.Context, *CreateReturnHomeShipmentRequest) (*CreateReturnShipmentResponse, error)
	// 查詢賣家退貨設定
	GetSellerReturnConfig(context.Context, *GetSellerReturnConfigRequest) (*GetSellerReturnConfigResponse, error)
	// 退貨出貨便列印重試（AfterSales ops retry 用，驗證 is_return=true 後非同步觸發 PayUni print_label）
	RetryReturnPrintLabel(context.Context, *RetryReturnPrintLabelRequest) (*RetryReturnPrintLabelResponse, error)
	// 依訂單編號查詢 ShipTradeNo（區分正向/退貨）
	LookupShipTradeNo(context.Context, *LookupShipTradeNoRequest) (*LookupShipTradeNoResponse, error)
	// 列物流異常（含正向+退貨）。abnormal_only=true 的判準 = 平台失敗態 OR provider_error_code 非空。
	// 🔴 判準**不是** provider_status——那欄保存的是物流商原始貨態（含正常軌跡與尚未 mapping 的
	// 未知值），以「有值」判異常會把每張正常單撈進來（V12 拆欄修正）。
	ListShipmentsForAdmin(context.Context, *ListShipmentsForAdminRequest) (*ListShipmentsForAdminResponse, error)
	// 取單一物流單詳情（Admin 對帳用，含完整 provider_* 與寄收件資訊）
	GetShipmentForAdmin(context.Context, *GetShipmentForAdminRequest) (*GetShipmentForAdminResponse, error)
	// 列建店異常（預設 onboarding_status=REJECTED；可 filter shipping_type / provider_status）
	ListSellerShipmentSettingsForAdmin(context.Context, *ListSellerShipmentSettingsForAdminRequest) (*ListSellerShipmentSettingsForAdminResponse, error)
	// 列賣家配送異常 dashboard（直接查 shipments 表 LEFT JOIN ack 表，無第二份狀態）
	ListSellerShipmentAnomalies(context.Context, *ListSellerShipmentAnomaliesRequest) (*ListSellerShipmentAnomaliesResponse, error)
	// 賣家配送異常統計（依 anomaly_type / severity 分組計數）
	GetSellerShipmentAnomalyStats(context.Context, *GetSellerShipmentAnomalyStatsRequest) (*GetSellerShipmentAnomalyStatsResponse, error)
	// 賣家標記異常為「已處理」（upsert shipment_anomaly_acknowledgments）
	AcknowledgeShipmentAnomaly(context.Context, *AcknowledgeShipmentAnomalyRequest) (*AcknowledgeShipmentAnomalyResponse, error)
	// 賣家標記異常為「已忽略」
	IgnoreShipmentAnomaly(context.Context, *IgnoreShipmentAnomalyRequest) (*IgnoreShipmentAnomalyResponse, error)
	// Admin 平台級配送異常監控
	ListShipmentAnomaliesForAdmin(context.Context, *ListShipmentAnomaliesForAdminRequest) (*ListShipmentAnomaliesForAdminResponse, error)
	// Admin 標記異常為「已處理」（issue #1327；actor_type='ADMIN'，與賣家 ack 互不覆蓋）
	AcknowledgeShipmentAnomalyForAdmin(context.Context, *AcknowledgeShipmentAnomalyForAdminRequest) (*AcknowledgeShipmentAnomalyResponse, error)
	// Admin 標記異常為「已忽略」（issue #1327）
	IgnoreShipmentAnomalyForAdmin(context.Context, *IgnoreShipmentAnomalyForAdminRequest) (*IgnoreShipmentAnomalyResponse, error)
	// 取得（或沿用）一筆 Uber 報價。冪等：同一車在 TTL 內重複呼叫回同一個 quote_id。
	GetUberQuoteForCheckout(context.Context, *GetUberQuoteForCheckoutRequest) (*GetUberQuoteForCheckoutResponse, error)
	// confirm（capture 前）重驗 TTL 與購物車一致性；capture 後把報價標成已確認。
	ValidateUberQuoteForCheckout(context.Context, *ValidateUberQuoteForCheckoutRequest) (*ValidateUberQuoteForCheckoutResponse, error)
	// 賣家列自己的 Uber 配送。🔴 歸屬由服務端以 store_id 強制，不接受呼叫端指定。
	ListSellerUberDeliveries(context.Context, *ListSellerUberDeliveriesRequest) (*ListSellerUberDeliveriesResponse, error)
	// 賣家看單筆 Uber 配送詳情（含 quote／POD／allowed_actions）。
	GetSellerUberDelivery(context.Context, *GetSellerUberDeliveryRequest) (*GetSellerUberDeliveryResponse, error)
	// Admin 列平台全部 Uber 配送（W6-4 Delivery List 的九個篩選維度）。
	ListUberDeliveriesForAdmin(context.Context, *ListUberDeliveriesForAdminRequest) (*ListUberDeliveriesForAdminResponse, error)
	// Admin 看單筆 Uber 配送詳情（再加 timeline 與 provider raw payload）。
	GetUberDeliveryForAdmin(context.Context, *GetUberDeliveryForAdminRequest) (*GetUberDeliveryForAdminResponse, error)
	mustEmbedUnimplementedShippingServiceServer()
}

